69:     if (!raw) return defaultSave();
70:     const parsed = JSON.parse(raw);
71:     return {
72:       ...defaultSave(),
73:       ...parsed,
74:       stars: parsed.stars || {},
75:       best: parsed.best || {},
76:       sound: parsed.sound !== false,
77:     };
78:   } catch {
79:     return defaultSave();
