292: async function startLevel(id) {
293:   const level = LEVELS.find((l) => l.id === id);
294:   if (!level) return;
295: 
296:   audio.ensure();
297:   if (!spritesReady) {
298:     try { await loadSprites(); spritesReady = true; } catch {}
299:   }
300: 
301:   const token = ++sessionToken;
302:   destroyCurrent();
303:   sessionToken = token;
304: 
305:   homeScreen.hidden = true;
306:   gameScreen.hidden = false;
307: 
308:   gameTitle.textContent = level.title;
309:   gameClaim.textContent = level.claim;
310:   gameSponsor.textContent = level.studio;
311:   adBannerText.textContent = BANNER_COPY[0];
312: 
313:   startSkipTimer();
314:   startBannerCycle();
315:   showHint(level.hint, 4200);
316: 
317:   const api = {
318:     win(stars, score, opts = {}) {
319:       if (token !== sessionToken || !current || current.resultShown) return;
320:       current.resultShown = true;
321:       const starCount = Math.max(1, Math.min(3, stars | 0));
322:       const prevStars = save.stars[level.id] || 0;
323:       save.stars[level.id] = Math.max(prevStars, starCount);
324:       const prevBest = save.best[level.id];
325:       const numericScore = Number(score) || 0;
326:       if (prevBest == null || (level.lowerBetter ? numericScore < prevBest : numericScore > prevBest)) {
327:         save.best[level.id] = numericScore;
328:       }
329:       persist();
330:       renderHome();
331:       stopSkipTimer("AD ENDED");
332:       showHint("Ad complete. Suspiciously fun, right?", 1400);
333:       showResult({ level, token, win: true, stars: starCount, score: numericScore, opts });
334:     },
335:     lose(reason) {
336:       if (token !== sessionToken || !current || current.resultShown) return;
337:       current.resultShown = true;
338:       stopSkipTimer("AD ENDED");
339:       showResult({ level, token, win: false, stars: 0, score: null, opts: { note: reason } });
340:     },
341:     toast(message, ms) {
342:       if (token === sessionToken) showToast(message, ms);
343:     },
344:     vibrate(pattern) {
345:       try { navigator.vibrate?.(pattern); } catch {}
346:     },
347:   };
348: 
349:   try {
350:     const instance = level.mount(levelHost, api);
351:     if (token !== sessionToken) {
352:       instance?.destroy?.();
353:       return;
354:     }
355:     current = { id: level.id, level, token, instance, resultShown: false };
356:     if (level.id === "squad") {
357:       // nothing extra; the level explains itself in the hint chip
358:     }
359:   } catch (error) {
360:     console.error(error);
361:     showToast("The ad failed to load. Ironic.", 3000);
362:     goHome();
363:   }
364: }
