366: function formatScore(level, score) {
367:   if (score == null) return "";
368:   switch (level.id) {
369:     case "knife": return `${score} / 3`;
370:     case "sort": return `${score} MOVES`;
371:     case "squad": return `${score} SQUAD`;
372:     case "survivor": return `${score} KILLS`;
373:     case "bullet": return `${score} GRAZES`;
374:     case "snake": return `SIZE ${score}`;
375:     case "rescue": return `${score} BLOCKED`;
376:     default: return String(score);
377:   }
378: }
