380: function formatBest(level, value) {
381:   if (value == null) return "";
382:   switch (level.id) {
383:     case "knife": return `BEST ${value} / 3 APPLES`;
384:     case "sort": return `BEST ${value} MOVES`;
385:     case "squad": return `BEST SQUAD ${value}`;
386:     case "survivor": return `BEST ${value} KILLS`;
387:     case "bullet": return `BEST ${value} GRAZES`;
388:     case "snake": return `BEST SIZE ${value}`;
389:     case "rescue": return `BEST ${value} BLOCKED`;
390:     default: return `BEST ${value}`;
391:   }
392: }
