394: function confettiMarkup() {
395:   const colors = ["#ffd23f", "#ff5d8c", "#3ee9a5", "#62b6ff", "#9b5cff", "#ff8a3d"];
396:   let html = '<div class="confetti" aria-hidden="true">';
397:   for (let i = 0; i < 26; i++) {
398:     const left = Math.round(Math.random() * 96);
399:     const color = colors[i % colors.length];
400:     const delay = (Math.random() * 0.5).toFixed(2);
401:     const dur = (1.6 + Math.random() * 1.2).toFixed(2);
402:     const w = 4 + Math.round(Math.random() * 5);
403:     const h = 7 + Math.round(Math.random() * 9);
404:     html += `<i style="left:${left}%;background:${color};--delay:${delay}s;--dur:${dur}s;width:${w}px;height:${h}px"></i>`;
405:   }
406:   return html + "</div>";
407: }
