409: function showResult({ level, token, win, stars, score, opts = {} }) {
410:   if (token !== sessionToken) return;
411:   resultLayer.hidden = false;
412:   resultLayer.classList.toggle("lose", !win);
413: 
414:   const levelIndex = LEVELS.findIndex((l) => l.id === level.id);
415:   const isLast = levelIndex === LEVELS.length - 1;
416:   const next = nextLevel(level.id);
417:   const best = save.best[level.id];
418: 
419:   const kicker = win ? (isLast ? "SEASON FINALE" : "AD COMPLETE") : "AD WINS";
420:   const title = win ? (isLast && allCleared() ? "SEASON<br>CLEARED!" : "LEVEL<br>CLEAR!") : "AD GOT<br>YOU";
421:   const sub = win
422:     ? (opts.note || "The ad has been defeated. It will remember this.")
423:     : (opts.note || "The ad got you. This is exactly what it wanted.");
424: 
425:   const primaryAction = win ? (isLast ? "menu" : "next") : "retry";
426:   const primaryLabel = win ? (isLast ? "BACK TO THE AD BREAK" : "NEXT AD →") : "TRY AGAIN";
427:   const showReplay = win;
428:   const showMenu = !win || !isLast;
429: 
430:   resultLayer.innerHTML = `
431:     ${win ? confettiMarkup() : ""}
432:     <div class="result-card" role="dialog" aria-modal="true" aria-labelledby="result-title">
433:       <span class="result-stamp">${win ? "NOT AN AD" : "SKIPPABLE"}</span>
434:       <span class="result-kicker">${kicker}</span>
435:       <h2 class="result-title" id="result-title">${title}</h2>
436:       <p class="result-sub">${sub}</p>
437:       ${win ? `<div class="result-stars" aria-label="${stars} of 3 stars">${starsMarkup(stars)}</div>` : ""}
438:       ${win && score != null ? `
439:         <div class="result-score">
440:           <span class="score-val">${formatScore(level, score)}</span>
441:           <span class="score-best">${formatBest(level, best)}</span>
442:         </div>
443:       ` : ""}
444:       ${win && opts.note ? "" : ""}
445:       <div class="result-actions">
446:         <button class="result-primary" data-action="${primaryAction}" type="button">${primaryLabel}</button>
447:         <div class="result-secondary-row">
448:           ${showReplay ? `<button class="result-primary ghost" data-action="replay" type="button">REPLAY</button>` : ""}
449:           ${showMenu ? `<button class="result-primary ghost" data-action="menu" type="button">MENU</button>` : ""}
450:         </div>
451:         ${win && !isLast ? `<button class="result-link" data-action="menu" type="button">I'VE HAD ENOUGH ADS</button>` : ""}
452:         ${!win ? `<button class="result-link" data-action="menu" type="button">SKIP TO THE AD BREAK</button>` : ""}
453:       </div>
454:     </div>
455:   `;
456: 
457:   resultLayer.querySelectorAll("[data-action]").forEach((btn) => {
458:     btn.addEventListener("click", () => {
459:       const action = btn.dataset.action;
460:       audio.click();
461:       if (action === "next") startLevel(next.id);
462:       else if (action === "retry") startLevel(level.id);
463:       else if (action === "replay") startLevel(level.id);
464:       else goHome({ toast: "Back to the ad break." });
465:     });
466:   });
467: }
