537: async function boot() {
538:   audio.setEnabled(save.sound);
539:   updateSoundButton();
540:   renderHome();
541:   bindChrome();
542: 
543:   document.addEventListener("pointerdown", () => audio.ensure(), { once: true });
544:   window.addEventListener("keydown", (e) => {
545:     if (e.key === "Escape" && !gameScreen.hidden) {
546:       goHome({ toast: "Escaped the ad. Respect." });
547:     }
548:   });
549: 
550:   try {
