120:       const a = rand(0, TAU);
121:       const s = rand(power * 0.3, power);
122:       state.particles.push({
123:         x, y,
124:         vx: Math.cos(a) * s,
125:         vy: Math.sin(a) * s - 40,
126:         life: rand(0.35, 0.75),
127:         max: 0.75,
128:         size: rand(2, 5),
129:         color,
130:       });
131:     }
132:   }
133: 
134:   function applyOp(gate, side) {
135:     const op = gate.ops[side];
136:     const before = state.count;
137:     if (op.kind === "mul") state.count = Math.max(0, Math.round(state.count * op.value));
138:     else state.count = Math.max(0, state.count + op.value);
139:     const gained = state.count - before;
140:     const good = gained >= 0;
141:     addFloat(`${op.label}  ${gained >= 0 ? "+" : ""}${gained}`, good ? "#2ee6a6" : "#ff5d6c", state.x * stage.w, stage.h * 0.55, 1.25);
142:     burst(state.x * stage.w, stage.h * 0.68, good ? "#ffd23f" : "#ff5d6c", 14, 210);
143:     gate.flash = 0.5;
144:     state.flash = 0.18;
145:     if (op.kind === "mul") audio.good(); else audio.pop();
146:     if (state.count <= 0 && !state.finished) {
147:       state.finished = true;
148:       state.phase = "dead";
149:       setTimeout(() => api.lose("Your whole squad got wiped before the boss."), 650);
150:     }
151:     api.vibrate?.(10);
152:   }
153: 
154:   function update(dt) {
155:     state.time += dt;
156:     input.endFrame();
157:     if (state.phase === "run") {
158:       // steering
159:       let steer = 0;
160:       if (input.isDown("arrowleft", "a")) steer -= 1;
161:       if (input.isDown("arrowright", "d")) steer += 1;
162:       if (steer) state.targetX = clamp(state.targetX + steer * 1.35 * dt, 0.12, 0.88);
163:       state.targetX = clamp(state.targetX, 0.12, 0.88);
164:       state.x = lerp(state.x, state.targetX, 1 - Math.exp(-11 * dt));
165: 
166:       state.progress += state.speed * dt;
167: 
168:       for (const gate of state.gates) {
169:         if (!gate.hit && state.progress >= gate.at) {
170:           gate.hit = true;
171:           const side = state.x < 0.5 ? 0 : 1;
172:           gate.chosen = side;
173:           applyOp(gate, side);
174:         }
175:         gate.flash = Math.max(0, gate.flash - dt);
176:       }
177: 
178:       for (const p of state.pickups) {
179:         if (!p.hit && state.progress >= p.at) {
180:           p.hit = true;
181:           if (Math.abs(state.x - p.x) < 0.095) {
182:             state.count = Math.max(0, state.count + p.value);
183:             const color = p.value > 0 ? "#ffd23f" : "#ff5d6c";
184:             addFloat(`${p.value > 0 ? "+" : ""}${p.value}`, color, p.x * stage.w, stage.h * 0.66, 1.1);
185:             burst(p.x * stage.w, stage.h * 0.69, color, p.value > 0 ? 9 : 14, 160);
186:             if (p.value > 0) audio.eat(); else audio.bad();
187:           }
188:         }
189:       }
190: 
191:       if (state.progress >= FINISH && state.phase === "run") {
192:         state.phase = "battle";
193:         state.battleT = 0;
194:         state.shake = 6;
195:         audio.bad();
196:         api.vibrate?.(35);
197:       }
198:     } else if (state.phase === "battle") {
199:       state.battleT += dt;
200:       state.shake = Math.max(0, state.shake - dt * 12);
201:       if (!state.finished && state.battleT > 1.5) {
202:         state.finished = true;
203:         state.phase = state.count >= BOSS_HP ? "won" : "lost";
204:         if (state.count >= BOSS_HP) {
205:           const stars = state.count >= 260 ? 3 : state.count >= 130 ? 2 : 1;
206:           api.win(stars, state.count, {
207:             note: state.count >= 260
208:               ? "The boss never stood a chance. Neither did your thumbs."
209:               : "Boss defeated. The ad would like you to install anyway.",
210:           });
211:         } else {
212:           api.lose(`You reached the boss with ${state.count}. You needed ${BOSS_HP}.`);
213:         }
214:       }
215:     }
216: 
217:     state.flash = Math.max(0, state.flash - dt * 2.4);
218:     state.indicator += dt;
219: 
220:     for (const f of state.floats) {
221:       f.life -= dt;
222:       f.y -= 42 * dt;
223:     }
224:     state.floats = state.floats.filter((f) => f.life > 0);
225: 
226:     for (const p of state.particles) {
227:       p.life -= dt;
228:       p.vy += 360 * dt;
229:       p.x += p.vx * dt;
230:       p.y += p.vy * dt;
231:       p.vx *= 1 - dt * 1.4;
232:     }
233:     state.particles = state.particles.filter((p) => p.life > 0);
234:   }
235: 
236:   function drawBackdrop(ctx, w, h) {
237:     const sky = ctx.createLinearGradient(0, 0, 0, h);
238:     sky.addColorStop(0, "#5ed5ff");
239:     sky.addColorStop(0.42, "#b9ecff");
240:     sky.addColorStop(0.72, "#ffe0ef");
241:     sky.addColorStop(1, "#ffc6dc");
242:     ctx.fillStyle = sky;
243:     ctx.fillRect(0, 0, w, h);
244: 
245:     // sun
246:     ctx.save();
247:     ctx.globalAlpha = 0.6;
248:     ctx.fillStyle = "#fff5b8";
249:     ctx.beginPath();
250:     ctx.arc(w * 0.78, h * 0.12, w * 0.13, 0, TAU);
251:     ctx.fill();
252:     ctx.restore();
253: 
254:     // parallax hills
255:     const scroll = state.progress * h;
256:     for (let layer = 0; layer < 2; layer++) {
257:       const baseY = h * (0.22 + layer * 0.08);
258:       const amp = h * (0.035 + layer * 0.012);
259:       ctx.fillStyle = layer === 0 ? "rgba(112, 220, 172, 0.55)" : "rgba(61, 195, 137, 0.45)";
260:       ctx.beginPath();
261:       ctx.moveTo(0, h);
262:       for (let x = 0; x <= w; x += 18) {
263:         const y = baseY + Math.sin((x + scroll * (0.18 + layer * 0.15)) * 0.018 + layer) * amp;
264:         ctx.lineTo(x, y);
265:       }
266:       ctx.lineTo(w, h);
267:       ctx.closePath();
268:       ctx.fill();
269:     }
270: 
271:     // clouds
272:     const cloudSprites = ["cloud"];
273:     for (let i = 0; i < 4; i++) {
274:       const cx = ((i * 173 - scroll * (0.06 + i * 0.014)) % (w + 180)) - 90;
275:       const cy = h * (0.06 + i * 0.06);
276:       drawSprite(ctx, cloudSprites[0], ((cx % (w + 180)) + (w + 180)) % (w + 180) - 90, cy, w * (0.22 + i * 0.025), { alpha: 0.55 + i * 0.08 });
277:     }
278: 
279:     // track
280:     const left = w * 0.085;
281:     const right = w * 0.915;
282:     ctx.save();
283:     ctx.fillStyle = "#ffe9c7";
284:     roundRect(ctx, left - 8, 0, right - left + 16, h, 0);
285:     ctx.fill();
286:     const road = ctx.createLinearGradient(left, 0, right, 0);
287:     road.addColorStop(0, "#ffd6ae");
288:     road.addColorStop(0.5, "#ffe6c6");
289:     road.addColorStop(1, "#ffd0a6");
290:     ctx.fillStyle = road;
291:     roundRect(ctx, left, 0, right - left, h, 0);
292:     ctx.fill();
293: 
294:     // scrolling rungs
295:     ctx.strokeStyle = "rgba(196, 106, 125, 0.16)";
296:     ctx.lineWidth = 2;
297:     for (let d = -1; d < state.progress + 1.4; d += 0.16) {
298:       const y = h * 0.72 + (state.progress - d) * h;
299:       if (y < -20 || y > h + 20) continue;
300:       ctx.beginPath();
301:       ctx.moveTo(left + 12, y);
302:       ctx.lineTo(right - 12, y);
303:       ctx.stroke();
304:     }
305: 
306:     // center dashes
307:     ctx.setLineDash([14, 18]);
308:     ctx.lineDashOffset = (scroll % 32);
309:     ctx.strokeStyle = "rgba(255, 255, 255, 0.72)";
310:     ctx.lineWidth = 3;
311:     ctx.beginPath();
312:     ctx.moveTo(w / 2, 0);
313:     ctx.lineTo(w / 2, h);
314:     ctx.stroke();
315:     ctx.setLineDash([]);
316: 
317:     // fences
318:     for (const x of [left - 4, right + 4]) {
319:       ctx.fillStyle = "#b96b7e";
320:       ctx.fillRect(x - 2, 0, 4, h);
321:       for (let d = -1; d < state.progress + 1.4; d += 0.08) {
322:         const y = h * 0.72 + (state.progress - d) * h;
323:         if (y < -10 || y > h + 10) continue;
324:         ctx.fillStyle = "#ff9ab7";
325:         ctx.beginPath();
326:         ctx.arc(x, y, 3.4, 0, TAU);
327:         ctx.fill();
328:       }
329:     }
330: 
331:     // side vegetation
332:     for (let i = 0; i < 6; i++) {
333:       const d = -0.4 + i * 1.05;
334:       const y = h * 0.72 + (state.progress - d) * h;
335:       drawSprite(ctx, i % 2 ? "bush" : "flower", i % 2 ? w * 0.045 : w * 0.95, ((y % (h * 1.8)) + h * 1.8) % (h * 1.8) - h * 0.4, i % 2 ? w * 0.15 : w * 0.09, { alpha: 0.9 });
336:     }
337:     ctx.restore();
338:   }
339: 
340:   function gateScreenY(gate, h) {
341:     return h * 0.72 + (state.progress - gate.at) * h;
342:   }
343: 
344:   function drawGate(ctx, gate, w, h, index) {
345:     const y = gateScreenY(gate, h);
346:     const gateH = Math.min(h * 0.16, 120);
347:     if (y < -gateH || y > h + gateH) return;
348:     const left = w * 0.085;
349:     const right = w * 0.915;
350:     const mid = w / 2;
351:     const pad = 4;
352:     const chosenWorld = state.x < 0.5 ? 0 : 1;
353: 
354:     for (let side = 0; side < 2; side++) {
355:       const x = side === 0 ? left : mid;
356:       const pw = mid - left - pad;
357:       const op = gate.ops[side];
358:       const isChosen = gate.hit && gate.chosen === side;
359:       const active = !gate.hit && side === chosenWorld;
360:       const strong = op.kind === "mul" || (op.kind === "add" && op.value >= 20);
361:       const base = strong ? "#2ee6a6" : "#ffd23f";
362:       const alpha = gate.hit ? (isChosen ? 0.34 : 0.1) : active ? 0.34 : 0.22;
363:       ctx.save();
364:       ctx.globalAlpha = alpha;
365:       ctx.fillStyle = base;
366:       roundRect(ctx, x + pad, y - gateH / 2, pw - pad * 2, gateH, 14);
367:       ctx.fill();
368:       ctx.globalAlpha = gate.hit ? (isChosen ? 1 : 0.35) : active ? 1 : 0.65;
369:       ctx.strokeStyle = strong ? "#0d8f63" : "#b07b00";
370:       ctx.lineWidth = active ? 4 : 3;
371:       roundRect(ctx, x + pad, y - gateH / 2, pw - pad * 2, gateH, 14);
372:       ctx.stroke();
373:       ctx.globalAlpha = gate.hit ? (isChosen ? 1 : 0.25) : 1;
374:       ctx.fillStyle = "#20142e";
375:       ctx.textAlign = "center";
376:       ctx.textBaseline = "middle";
377:       ctx.font = `900 ${Math.round(clamp(w * 0.09, 22, 40))}px ${DISPLAY}`;
378:       ctx.fillText(op.label, x + pw / 2, y + 2);
379:       if (strong && !gate.hit) {
380:         ctx.font = `900 ${Math.round(clamp(w * 0.022, 8, 11))}px ${DISPLAY}`;
381:         ctx.fillStyle = "rgba(20, 12, 30, 0.62)";
382:         ctx.fillText(op.kind === "mul" ? "MULTIPLY" : "BIG GAIN", x + pw / 2, y + gateH * 0.3);
383:       }
384:       if (gate.hit && isChosen) {
385:         ctx.fillStyle = "#20142e";
386:         ctx.font = `900 ${Math.round(clamp(w * 0.022, 8, 11))}px ${DISPLAY}`;
387:         ctx.fillText("CHOSEN", x + pw / 2, y + gateH * 0.3);
388:       }
389:       ctx.restore();
390:     }
391: 
392:     // gate posts
393:     ctx.save();
394:     ctx.fillStyle = "#a05d75";
395:     ctx.globalAlpha = 0.55;
396:     ctx.fillRect(left - 7, y - gateH * 0.58, 5, gateH * 1.16);
397:     ctx.fillRect(right + 2, y - gateH * 0.58, 5, gateH * 1.16);
398:     ctx.restore();
399:   }
