401:   function drawPickup(ctx, p, w, h) {
402:     const y = gateScreenY(p, h);
403:     const x = p.x * w;
404:     if (y < -40 || y > h + 40) return;
405:     const bob = Math.sin(state.time * 5 + p.bob) * 3;
406:     ctx.save();
407:     ctx.globalAlpha = p.hit ? 0.18 : 1;
408:     if (p.type === "coin") {
409:       drawSprite(ctx, "coin", x, y + bob, clamp(w * 0.085, 24, 36), { rot: Math.sin(state.time * 2 + p.bob) * 0.18 });
410:       ctx.fillStyle = "#7a4100";
411:       ctx.font = `900 ${Math.round(clamp(w * 0.027, 10, 13))}px ${DISPLAY}`;
412:       ctx.textAlign = "center";
413:       ctx.fillText("+6", x, y + 27);
414:     } else if (p.type === "bomb") {
415:       drawSprite(ctx, "bomb", x, y + bob, clamp(w * 0.09, 26, 38));
416:       ctx.fillStyle = "#8b1e34";
417:       ctx.font = `900 ${Math.round(clamp(w * 0.027, 10, 13))}px ${DISPLAY}`;
418:       ctx.textAlign = "center";
419:       ctx.fillText("-7", x, y + 28);
420:     } else {
421:       drawSprite(ctx, "runnerB", x, y + bob, clamp(w * 0.08, 24, 34));
422:       ctx.strokeStyle = "rgba(255,255,255,0.9)";
423:       ctx.lineWidth = 2;
424:       ctx.beginPath();
425:       ctx.arc(x, y + bob, clamp(w * 0.055, 17, 24), 0, TAU);
426:       ctx.stroke();
427:       ctx.fillStyle = "#0c6c48";
428:       ctx.font = `900 ${Math.round(clamp(w * 0.026, 9, 12))}px ${DISPLAY}`;
429:       ctx.textAlign = "center";
430:       ctx.fillText("+4", x, y + 27);
431:     }
432:     ctx.restore();
433:   }
