435:   function drawCrowd(ctx, w, h) {
436:     const playerY = h * 0.72;
437:     let px = state.x * w;
438:     let py = playerY;
439:     if (state.phase === "battle") {
440:       const t = Math.min(1, state.battleT / 1.2);
441:       py -= easeOutCubic(t) * h * 0.16;
442:     }
443:     if (state.phase === "won") py -= h * 0.16;
444: 
445:     // shadow + formation
446:     ctx.save();
447:     ctx.fillStyle = "rgba(72, 31, 62, 0.22)";
448:     ctx.beginPath();
449:     ctx.ellipse(px, playerY + 17, Math.min(w * 0.16, 62), 12, 0, 0, TAU);
450:     ctx.fill();
451: 
452:     const visual = clamp(Math.ceil(state.count / 3) + 2, 3, state.crowd.length);
453:     const members = state.crowd.slice(0, visual);
454:     const scale = clamp(w * 0.082, 25, 40);
455:     const spread = clamp(0.6 + Math.sqrt(state.count) * 0.09, 0.8, 2.1);
456:     const bob = Math.sin(state.time * 11) * 2;
457:     const sorted = [...members].sort((a, b) => a.oy - b.oy);
458:     for (const m of sorted) {
459:       const wobble = Math.sin(state.time * 10 + m.phase) * 2;
460:       const mx = px + m.ox * scale * spread * 0.34;
461:       const my = py + m.oy * scale * spread * 0.3 + wobble + bob;
462:       const look = m.look === 0 ? "runnerA" : m.look === 1 ? "runnerB" : "runnerC";
463:       ctx.globalAlpha = 0.95;
464:       drawSprite(ctx, look, mx, my, scale);
465:     }
466:     ctx.restore();
467: 
468:     // count badge
469:     const badgeW = clamp(w * 0.2, 74, 100);
470:     const badgeH = clamp(h * 0.042, 27, 34);
471:     ctx.save();
472:     ctx.shadowColor = "rgba(0,0,0,0.28)";
473:     ctx.shadowBlur = 10;
474:     ctx.shadowOffsetY = 3;
475:     ctx.fillStyle = "#20142e";
476:     roundRect(ctx, px - badgeW / 2, py - scale * 1.5 - 12, badgeW, badgeH, badgeH / 2);
477:     ctx.fill();
478:     ctx.shadowColor = "transparent";
479:     ctx.fillStyle = "#ffd23f";
480:     ctx.font = `900 ${Math.round(badgeH * 0.58)}px ${DISPLAY}`;
481:     ctx.textAlign = "center";
482:     ctx.textBaseline = "middle";
483:     ctx.fillText(`× ${state.count}`, px, py - scale * 1.5 - 12 + badgeH / 2 + 1);
484:     ctx.restore();
485:   }
