487:   function drawBoss(ctx, w, h) {
488:     const y = gateScreenY({ at: FINISH + 0.28 }, h);
489:     if (y > h + 100) return;
490:     const castleSize = clamp(w * 0.5, 150, 250);
491:     const ogreSize = clamp(w * 0.34, 105, 170);
492:     ctx.save();
493:     drawSprite(ctx, "castle", w * 0.5, y - castleSize * 0.18, castleSize);
494:     const defeated = state.phase === "won" || (state.phase === "battle" && state.count >= BOSS_HP && state.battleT > 0.9);
495:     ctx.globalAlpha = defeated ? 0.35 : 1;
496:     drawSprite(ctx, "ogre", w * 0.5, y + castleSize * 0.26, ogreSize, {
497:       rot: defeated ? 0.3 : Math.sin(state.time * 3) * 0.025,
498:     });
499:     ctx.restore();
500: 
501:     if (y < h * 0.62) {
502:       const hpW = w * 0.5;
503:       const hpX = w / 2 - hpW / 2;
504:       const hpY = Math.max(66, y - castleSize * 0.58);
505:       ctx.save();
506:       ctx.fillStyle = "rgba(20, 12, 30, 0.55)";
507:       roundRect(ctx, hpX, hpY, hpW, 11, 6);
508:       ctx.fill();
509:       const fill = state.phase === "battle" ? clamp(1 - state.battleT / 1.5, 0, 1) : 1;
510:       ctx.fillStyle = "#ff5d6c";
511:       roundRect(ctx, hpX + 1.5, hpY + 1.5, (hpW - 3) * fill, 8, 5);
512:       ctx.fill();
513:       ctx.fillStyle = "#fff";
514:       ctx.font = `900 ${Math.round(clamp(w * 0.024, 9, 12))}px ${DISPLAY}`;
515:       ctx.textAlign = "center";
516:       ctx.fillText(`BOSS ${BOSS_HP}`, w / 2, hpY - 5);
517:       ctx.restore();
518:     }
519:   }
