556:   function drawFloats(ctx) {
557:     for (const f of state.floats) {
558:       const t = f.life / f.max;
559:       ctx.save();
560:       ctx.globalAlpha = clamp(t * 1.7, 0, 1);
561:       ctx.fillStyle = f.color;
562:       ctx.strokeStyle = "rgba(20,12,30,0.5)";
563:       ctx.lineWidth = 4;
564:       ctx.font = `900 ${Math.round(clamp(stage.w * 0.075, 20, 30) * f.size)}px ${DISPLAY}`;
565:       ctx.textAlign = "center";
566:       ctx.strokeText(f.text, f.x, f.y);
567:       ctx.fillText(f.text, f.x, f.y);
568:       ctx.restore();
569:     }
570:   }
