572:   function drawParticles(ctx) {
573:     for (const p of state.particles) {
574:       const a = clamp(p.life / p.max, 0, 1);
575:       ctx.globalAlpha = a;
576:       ctx.fillStyle = p.color;
577:       ctx.beginPath();
578:       ctx.arc(p.x, p.y, p.size * a + 0.5, 0, TAU);
579:       ctx.fill();
580:     }
581:     ctx.globalAlpha = 1;
582:   }
