584:   function draw() {
585:     const { ctx } = stage;
586:     const w = stage.w;
587:     const h = stage.h;
588:     ctx.save();
589:     if (state.shake > 0) {
590:       ctx.translate(rand(-state.shake, state.shake), rand(-state.shake, state.shake));
591:     }
592: 
593:     drawBackdrop(ctx, w, h);
594: 
595:     // draw world objects, sorted by depth
596:     const objects = [];
597:     for (const gate of state.gates) objects.push({ type: "gate", y: gateScreenY(gate, h), gate });
598:     for (const p of state.pickups) objects.push({ type: "pickup", y: gateScreenY(p, h), p });
599:     objects.sort((a, b) => a.y - b.y);
600: 
601:     for (const obj of objects) {
602:       if (obj.type === "gate") drawGate(ctx, obj.gate, w, h);
603:       else drawPickup(ctx, obj.p, w, h);
604:     }
605: 
