78:         if (roll < t.weight) { picked = t; break; }
79:         roll -= t.weight;
80:       }
81:       return {
82:         at: d,
83:         x: rand(0.16, 0.84),
84:         type: picked.type,
85:         value: picked.value,
86:         hit: false,
87:         bob: Math.random() * TAU,
88:       };
89:     };
90:     state.pickups.push(spawn(0.34));
91:     for (let i = 0; i < GATE_AT.length; i++) {
92:       const start = GATE_AT[i] + 0.12;
93:       const end = i < GATE_AT.length - 1 ? GATE_AT[i + 1] - 0.1 : FINISH - 0.24;
94:       state.pickups.push(spawn(rand(start, Math.max(start + 0.05, end))));
95:       if (i % 2 === 0) state.pickups.push(spawn(rand(start, Math.max(start + 0.05, end))));
96:     }
97:   }
