99:   let pointerActive = false;
100:   const stopPointer = bindPointer(stage.canvas, {
101:     down(p) {
102:       pointerActive = true;
103:       state.targetX = clamp(p.x / stage.w, 0.12, 0.88);
104:     },
105:     move(p, e) {
106:       if (pointerActive || e.pointerType === "mouse") {
107:         state.targetX = clamp(p.x / stage.w, 0.12, 0.88);
108:       }
109:     },
110:     up() { pointerActive = false; },
111:     leave() { pointerActive = false; },
112:   });
