114:   function addFloat(text, color, x, y, size = 1) {
115:     state.floats.push({ text, color, x, y, life: 1.15, max: 1.15, size });
116:   }
117: 
118:   function burst(x, y, color, amount = 10, power = 180) {
119:     for (let i = 0; i < amount; i++) {
120:       const a = rand(0, TAU);
121:       const s = rand(power * 0.3, power);
122:       state.particles.push({
123:         x, y,
124:         vx: Math.cos(a) * s,
125:         vy: Math.sin(a) * s - 40,
126:         life: rand(0.35, 0.75),
127:         max: 0.75,
128:         size: rand(2, 5),
129:         color,
130:       });
131:     }
132:   }
