236:   function drawBackdrop(ctx, w, h) {
237:     const sky = ctx.createLinearGradient(0, 0, 0, h);
238:     sky.addColorStop(0, "#5ed5ff");
239:     sky.addColorStop(0.42, "#b9ecff");
240:     sky.addColorStop(0.72, "#ffe0ef");
241:     sky.addColorStop(1, "#ffc6dc");
242:     ctx.fillStyle = sky;
243:     ctx.fillRect(0, 0, w, h);
244: 
245:     // sun
246:     ctx.save();
247:     ctx.globalAlpha = 0.6;
248:     ctx.fillStyle = "#fff5b8";
249:     ctx.beginPath();
250:     ctx.arc(w * 0.78, h * 0.12, w * 0.13, 0, TAU);
251:     ctx.fill();
252:     ctx.restore();
253: 
254:     // parallax hills
255:     const scroll = state.progress * h;
256:     for (let layer = 0; layer < 2; layer++) {
257:       const baseY = h * (0.22 + layer * 0.08);
258:       const amp = h * (0.035 + layer * 0.012);
259:       ctx.fillStyle = layer === 0 ? "rgba(112, 220, 172, 0.55)" : "rgba(61, 195, 137, 0.45)";
260:       ctx.beginPath();
261:       ctx.moveTo(0, h);
262:       for (let x = 0; x <= w; x += 18) {
263:         const y = baseY + Math.sin((x + scroll * (0.18 + layer * 0.15)) * 0.018 + layer) * amp;
264:         ctx.lineTo(x, y);
265:       }
266:       ctx.lineTo(w, h);
267:       ctx.closePath();
268:       ctx.fill();
269:     }
270: 
271:     // clouds
272:     const cloudSprites = ["cloud"];
273:     for (let i = 0; i < 4; i++) {
274:       const cx = ((i * 173 - scroll * (0.06 + i * 0.014)) % (w + 180)) - 90;
275:       const cy = h * (0.06 + i * 0.06);
276:       drawSprite(ctx, cloudSprites[0], ((cx % (w + 180)) + (w + 180)) % (w + 180) - 90, cy, w * (0.22 + i * 0.025), { alpha: 0.55 + i * 0.08 });
277:     }
278: 
279:     // track
280:     const left = w * 0.085;
281:     const right = w * 0.915;
282:     ctx.save();
283:     ctx.fillStyle = "#ffe9c7";
284:     roundRect(ctx, left - 8, 0, right - left + 16, h, 0);
285:     ctx.fill();
286:     const road = ctx.createLinearGradient(left, 0, right, 0);
287:     road.addColorStop(0, "#ffd6ae");
288:     road.addColorStop(0.5, "#ffe6c6");
289:     road.addColorStop(1, "#ffd0a6");
290:     ctx.fillStyle = road;
291:     roundRect(ctx, left, 0, right - left, h, 0);
292:     ctx.fill();
293: 
294:     // scrolling rungs
295:     ctx.strokeStyle = "rgba(196, 106, 125, 0.16)";
296:     ctx.lineWidth = 2;
297:     for (let d = -1; d < state.progress + 1.4; d += 0.16) {
298:       const y = h * 0.72 + (state.progress - d) * h;
299:       if (y < -20 || y > h + 20) continue;
300:       ctx.beginPath();
301:       ctx.moveTo(left + 12, y);
302:       ctx.lineTo(right - 12, y);
303:       ctx.stroke();
304:     }
305: 
306:     // center dashes
307:     ctx.setLineDash([14, 18]);
308:     ctx.lineDashOffset = (scroll % 32);
309:     ctx.strokeStyle = "rgba(255, 255, 255, 0.72)";
310:     ctx.lineWidth = 3;
311:     ctx.beginPath();
312:     ctx.moveTo(w / 2, 0);
313:     ctx.lineTo(w / 2, h);
314:     ctx.stroke();
315:     ctx.setLineDash([]);
316: 
317:     // fences
318:     for (const x of [left - 4, right + 4]) {
319:       ctx.fillStyle = "#b96b7e";
320:       ctx.fillRect(x - 2, 0, 4, h);
321:       for (let d = -1; d < state.progress + 1.4; d += 0.08) {
322:         const y = h * 0.72 + (state.progress - d) * h;
323:         if (y < -10 || y > h + 10) continue;
324:         ctx.fillStyle = "#ff9ab7";
325:         ctx.beginPath();
326:         ctx.arc(x, y, 3.4, 0, TAU);
327:         ctx.fill();
328:       }
329:     }
330: 
331:     // side vegetation
332:     for (let i = 0; i < 6; i++) {
333:       const d = -0.4 + i * 1.05;
334:       const y = h * 0.72 + (state.progress - d) * h;
335:       drawSprite(ctx, i % 2 ? "bush" : "flower", i % 2 ? w * 0.045 : w * 0.95, ((y % (h * 1.8)) + h * 1.8) % (h * 1.8) - h * 0.4, i % 2 ? w * 0.15 : w * 0.09, { alpha: 0.9 });
336:     }
337:     ctx.restore();
338:   }
