344:   function drawGate(ctx, gate, w, h, index) {
345:     const y = gateScreenY(gate, h);
346:     const gateH = Math.min(h * 0.16, 120);
347:     if (y < -gateH || y > h + gateH) return;
348:     const left = w * 0.085;
349:     const right = w * 0.915;
350:     const mid = w / 2;
351:     const pad = 4;
352:     const chosenWorld = state.x < 0.5 ? 0 : 1;
353: 
354:     for (let side = 0; side < 2; side++) {
355:       const x = side === 0 ? left : mid;
356:       const pw = mid - left - pad;
357:       const op = gate.ops[side];
358:       const isChosen = gate.hit && gate.chosen === side;
359:       const active = !gate.hit && side === chosenWorld;
360:       const strong = op.kind === "mul" || (op.kind === "add" && op.value >= 20);
361:       const base = strong ? "#2ee6a6" : "#ffd23f";
362:       const alpha = gate.hit ? (isChosen ? 0.34 : 0.1) : active ? 0.34 : 0.22;
363:       ctx.save();
364:       ctx.globalAlpha = alpha;
365:       ctx.fillStyle = base;
366:       roundRect(ctx, x + pad, y - gateH / 2, pw - pad * 2, gateH, 14);
367:       ctx.fill();
368:       ctx.globalAlpha = gate.hit ? (isChosen ? 1 : 0.35) : active ? 1 : 0.65;
369:       ctx.strokeStyle = strong ? "#0d8f63" : "#b07b00";
370:       ctx.lineWidth = active ? 4 : 3;
371:       roundRect(ctx, x + pad, y - gateH / 2, pw - pad * 2, gateH, 14);
372:       ctx.stroke();
373:       ctx.globalAlpha = gate.hit ? (isChosen ? 1 : 0.25) : 1;
374:       ctx.fillStyle = "#20142e";
375:       ctx.textAlign = "center";
376:       ctx.textBaseline = "middle";
377:       ctx.font = `900 ${Math.round(clamp(w * 0.09, 22, 40))}px ${DISPLAY}`;
378:       ctx.fillText(op.label, x + pw / 2, y + 2);
379:       if (strong && !gate.hit) {
380:         ctx.font = `900 ${Math.round(clamp(w * 0.022, 8, 11))}px ${DISPLAY}`;
381:         ctx.fillStyle = "rgba(20, 12, 30, 0.62)";
382:         ctx.fillText(op.kind === "mul" ? "MULTIPLY" : "BIG GAIN", x + pw / 2, y + gateH * 0.3);
383:       }
384:       if (gate.hit && isChosen) {
385:         ctx.fillStyle = "#20142e";
386:         ctx.font = `900 ${Math.round(clamp(w * 0.022, 8, 11))}px ${DISPLAY}`;
387:         ctx.fillText("CHOSEN", x + pw / 2, y + gateH * 0.3);
388:       }
389:       ctx.restore();
390:     }
391: 
392:     // gate posts
393:     ctx.save();
394:     ctx.fillStyle = "#a05d75";
395:     ctx.globalAlpha = 0.55;
396:     ctx.fillRect(left - 7, y - gateH * 0.58, 5, gateH * 1.16);
397:     ctx.fillRect(right + 2, y - gateH * 0.58, 5, gateH * 1.16);
398:     ctx.restore();
399:   }
