521:   function drawHud(ctx, w, h) {
522:     const pad = 11;
523:     const pillH = clamp(h * 0.042, 27, 34);
524: 
525:     ctx.save();
526:     ctx.fillStyle = "rgba(20, 12, 30, 0.55)";
527:     roundRect(ctx, pad, pad, clamp(w * 0.27, 96, 124), pillH, 9);
528:     ctx.fill();
529:     ctx.fillStyle = "#fff";
530:     ctx.font = `900 ${Math.round(pillH * 0.45)}px ${DISPLAY}`;
531:     ctx.textAlign = "left";
532:     ctx.textBaseline = "middle";
533:     ctx.fillText(`SQUAD  ${state.count}`, pad + 11, pad + pillH / 2 + 1);
534: 
535:     const bossW = clamp(w * 0.25, 84, 112);
536:     ctx.fillStyle = "rgba(20, 12, 30, 0.55)";
537:     roundRect(ctx, w - pad - bossW, pad, bossW, pillH, 9);
538:     ctx.fill();
539:     ctx.fillStyle = "#ff9fb0";
540:     ctx.font = `900 ${Math.round(pillH * 0.42)}px ${DISPLAY}`;
541:     ctx.textAlign = "center";
542:     ctx.fillText(state.count >= BOSS_HP ? `BOSS READY ✓` : `NEED ${BOSS_HP}`, w - pad - bossW / 2, pad + pillH / 2 + 1);
543: 
544:     // progress
545:     const barW = w - pad * 2;
546:     const barY = pad + pillH + 8;
547:     ctx.fillStyle = "rgba(20, 12, 30, 0.18)";
548:     roundRect(ctx, pad, barY, barW, 5, 3);
549:     ctx.fill();
550:     ctx.fillStyle = state.count >= BOSS_HP ? "#2ee6a6" : "#ffd23f";
551:     roundRect(ctx, pad, barY, barW * clamp(state.progress / FINISH, 0, 1), 5, 3);
552:     ctx.fill();
553:     ctx.restore();
554:   }
