556:   function drawFloats(ctx) {
557:     for (const f of state.floats) {
558:       const t = f.life / f.max;
559:       ctx.save();
560:       ctx.globalAlpha = clamp(t * 1.7, 0, 1);
561:       ctx.fillStyle = f.color;
562:       ctx.strokeStyle = "rgba(20,12,30,0.5)";
563:       ctx.lineWidth = 4;
564:       ctx.font = `900 ${Math.round(clamp(stage.w * 0.075, 20, 30) * f.size)}px ${DISPLAY}`;
565:       ctx.textAlign = "center";
566:       ctx.strokeText(f.text, f.x, f.y);
567:       ctx.fillText(f.text, f.x, f.y);
568:       ctx.restore();
569:     }
570:   }
571: 
572:   function drawParticles(ctx) {
573:     for (const p of state.particles) {
574:       const a = clamp(p.life / p.max, 0, 1);
575:       ctx.globalAlpha = a;
576:       ctx.fillStyle = p.color;
577:       ctx.beginPath();
578:       ctx.arc(p.x, p.y, p.size * a + 0.5, 0, TAU);
579:       ctx.fill();
580:     }
581:     ctx.globalAlpha = 1;
582:   }
583: 
584:   function draw() {
585:     const { ctx } = stage;
586:     const w = stage.w;
587:     const h = stage.h;
588:     ctx.save();
589:     if (state.shake > 0) {
590:       ctx.translate(rand(-state.shake, state.shake), rand(-state.shake, state.shake));
591:     }
592: 
593:     drawBackdrop(ctx, w, h);
594: 
595:     // draw world objects, sorted by depth
596:     const objects = [];
597:     for (const gate of state.gates) objects.push({ type: "gate", y: gateScreenY(gate, h), gate });
598:     for (const p of state.pickups) objects.push({ type: "pickup", y: gateScreenY(p, h), p });
599:     objects.sort((a, b) => a.y - b.y);
600: 
601:     for (const obj of objects) {
602:       if (obj.type === "gate") drawGate(ctx, obj.gate, w, h);
603:       else drawPickup(ctx, obj.p, w, h);
604:     }
605: 
606:     drawBoss(ctx, w, h);
607:     drawCrowd(ctx, w, h);
608:     drawParticles(ctx);
609:     drawFloats(ctx);
610:     drawHud(ctx, w, h);
611: 
612:     if (state.flash > 0) {
613:       ctx.globalAlpha = state.flash * 0.22;
614:       ctx.fillStyle = "#fff";
615:       ctx.fillRect(0, 0, w, h);
616:     }
617: 
618:     if (state.phase === "battle") {
619:       const t = state.battleT;
620:       if (t < 1.5) {
