584:   function draw() {
585:     const { ctx } = stage;
586:     const w = stage.w;
587:     const h = stage.h;
588:     ctx.save();
589:     if (state.shake > 0) {
590:       ctx.translate(rand(-state.shake, state.shake), rand(-state.shake, state.shake));
591:     }
592: 
593:     drawBackdrop(ctx, w, h);
